# Change the values as you see fit
EAST = "east"
NORTH = "north"
WEST = "west"
SOUTH = "south"


class Robot:
    def __init__(self, direction=NORTH, x_pos=0, y_pos=0):
        # primary direction attribute expected by tests
        self.direction = direction
        # coordinates
        self.x_pos = x_pos
        self.y_pos = y_pos

    @property
    def coordinates(self):
        return (self.x_pos, self.y_pos)

    def turn_right(self):
        order = [NORTH, EAST, SOUTH, WEST]
        try:
            idx = order.index(self.direction)
        except ValueError:
            return
        self.direction = order[(idx + 1) % 4]

    def turn_left(self):
        order = [NORTH, WEST, SOUTH, EAST]
        try:
            idx = order.index(self.direction)
        except ValueError:
            return
        self.direction = order[(idx + 1) % 4]

    def advance(self):
        if self.direction == NORTH:
            self.y_pos += 1
        elif self.direction == SOUTH:
            self.y_pos -= 1
        elif self.direction == EAST:
            self.x_pos += 1
        elif self.direction == WEST:
            self.x_pos -= 1

    def move(self, instructions):
        for ch in instructions:
            if ch == "R":
                self.turn_right()
            elif ch == "L":
                self.turn_left()
            elif ch == "A":
                self.advance()
            else:
                # ignore unknown instructions
                pass

    # alias for some test suites that expect simulate
    def simulate(self, instructions):
        self.move(instructions)
